    response.headers["X-Total-Count"] = "42"
    return [{"name": "a"}]

from fastapi.responses import (
    JSONResponse, PlainTextResponse, HTMLResponse,
    FileResponse, StreamingResponse
)
import io

@app.get("/text", response_class=PlainTextResponse)
def get_text():
    return "plain text"

@app.get("/download")
def download():
    return FileResponse("/path/to/report.pdf", filename="report.pdf")

@app.get("/stream")
def stream():
    def gen():
        for i in range(5):
            yield f"chunk {i}\n"
    return StreamingResponse(io.StringIO("".join(gen())), media_type="text/plain")
